parameters.jsCode:
const ev = $input.first().json.output ?? $input.first().json;
const app = $('Prepare Application').first().json;
const profile = $('Extract Candidate Profile').first().json.output || {};

const cv = (
  app.cvText ||
  app.CVtext ||
  app['CV Text'] ||
  app.text ||
  ''
).toLowerCase();

const problems = [];

// Validate score
if (!Number.isInteger(ev.score) || ev.score < 0 || ev.score > 100) {
  problems.push('score must be a whole number from 0 to 100');
}

// Validate recommendation
if (!['interview', 'maybe', 'reject'].includes(ev.recommendation)) {
  problems.push('recommendation must be interview, maybe or reject');
}

if (ev.recommendation === 'interview' && ev.score < 70) {
  problems.push('interview needs a score of 70 or more');
}

if (ev.recommendation === 'reject' && ev.score >= 40) {
  problems.push('reject needs a score below 40');
}

// Skills
const matched = ev.matched_skills || ev.matched_requirements || [];
const missing = ev.missing_skills || ev.missing_requirements || [];

if (!matched.length && !missing.length) {
  problems.push('the evaluation lists no requirements');
}

// Verify profile skills against CV
const unverified = (profile.skills || []).filter(
  s => !cv.includes(String(s).toLowerCase().split(' (')[0])
);

if (cv && unverified.length > 2) {
  problems.push('skills not found in the CV: ' + unverified.join(', '));
}

// Remove only unnecessary internal application fields
const {
  cvText,
  CVtext,
  'CV Text': _,
  jobRequirements,
  'Job Requirements ': __,
  ...applicant
} = app;

// Final output
return [{
  json: {
    ...applicant,
    ...ev,

    // Use evaluation experience first, then profile
    yearsExperience:
      ev.years_of_experience ??
      ev.years_experience ??
      profile.years_of_experience ??
      profile.years_experience ??
      '',

    // Top skills from candidate profile
    topSkills: (profile.skills || []).slice(0, 6).join(', '),

    valid: problems.length === 0,
    problems: problems.join('; ')
  }
}];
